negativeExample:
package com.example;

import java.net.URL;
import org.eclipse.core.runtime.CoreException;

public class MyClass {
    /**
     * Deprecated method with existing attributes, should not be matched by this rule
     * as the pattern is for a plain @Deprecated annotation.
     */
    @Deprecated(since = "9", forRemoval = false)
    public static void oldMethodWithExistingAttributes(URL resourceUrl, String realm) throws CoreException {
        System.out.println("Method with existing attributes called.");
    }

    /**
     * A different annotation, should not be affected.
     */
    @Override
    public String toString() {
        return "MyClass";
    }

    /**
     * A non-deprecated method, should not be affected.
     */
    public void nonDeprecatedMethod() {
        System.out.println("Non-deprecated method.");
    }
}
